// === HEATMAP RENDERING ===
function renderHeatmap(containerId, data, globalMedian, color) {
  const sorted = [...data].sort((a, b) => b.deviation - a.deviation);
  const maxAbs = Math.max(...sorted.map(d => Math.abs(d.deviation)));
  const container = document.getElementById(containerId);

  let html = '<div class="heatmap">';
  for (const d of sorted) {
    const isPos = d.deviation >= 0;
    const barPct = Math.round((Math.abs(d.deviation) / maxAbs) * 100);
    const barColor = isPos ? '#22c55e' : '#ef4444';
    const valColor = isPos ? '#22c55e' : '#ef4444';
    const sign = isPos ? '+' : '';
    const priceFmt = '$' + d.median.toLocaleString('en-US', {minimumFractionDigits:0, maximumFractionDigits:0});
    html += `
      <div class="heatmap-row">
        <div class="heatmap-label">${d.country}</div>
        <div class="heatmap-bar-wrap">
          ${isPos
            ? `<div style="width:50%;display:flex;justify-content:flex-end;padding-right:4px;"><div class="heatmap-bar" style="width:${barPct}%;background:${barColor};"></div></div><div style="width:50%"></div>`
            : `<div style="width:50%"></div><div style="display:flex;width:50%;padding-left:4px;"><div class="heatmap-bar" style="width:${barPct}%;background:${barColor};"></div></div>`
          }
        </div>
        <div class="heatmap-val" style="color:${valColor}">${sign}${d.deviation}%</div>
        <div style="font-size:12px;color:#94a3b8;width:70px;">${priceFmt}</div>
      </div>`;
  }
  html += '</div>';
  container.innerHTML = html;
}

